import {CFG,ITEMS,LAUNCHERS,ROUTES} from './data.js';
const copy=s=>structuredClone(s),clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
export const item=id=>ITEMS.find(i=>i.id===id); export const route=s=>ROUTES.find(r=>r.id===s.route); export const launcher=s=>LAUNCHERS[0];
export function fresh(players=1,seed=Math.floor(Math.random()*8973)+1000){return {version:CFG.version,phase:'lab',players:clamp(players,1,4),role:1,parts:[],route:'standard',launcher:'medium',grants:[],compared:[],day:0,log:[],flight:null,green:null,attempt:1,seed,rng:seed};}
export function stats(s){let p=s.parts.map(item),l=launcher(s),cost=p.reduce((a,i)=>a+i.cost,0),kg=p.reduce((a,i)=>a+i.kg,0),power=l.power+p.reduce((a,i)=>a+i.gen,0),use=p.reduce((a,i)=>a+i.w,0)+(s.flight?.extraW||0);return {cost,kg,use,power,arrivalPower:power*CFG.solarArrival,dv:CFG.rocketDv-kg*CFG.dvPerKg,budget:CFG.budget+s.grants.reduce((a,i)=>a+CFG.grants[i],0)-cost};}
export function log(s,en,es=en){s.log.push({day:s.day,en,es});}
export function errors(s){let t=stats(s),r=route(s),e=[];if(!s.parts.some(k=>item(k).kind==='chamber'))e.push(['Install a biological chamber.','Install a biological chamber.']);if(t.kg>250)e.push(['Payload exceeds 250 kg.','Payload exceeds 250 kg.']);if(t.arrivalPower<t.use)e.push(['Arrival power (generation × 0.85) does not cover demand. Add panels or remove equipment.','Arrival power (generation × 0.85) does not cover demand. Add panels or remove equipment.']);if(t.dv<r.dv)e.push([`Delta-v ${t.dv.toFixed(2)} km/s is below ${r.dv} km/s.`,`Delta-v ${t.dv.toFixed(2)} km/s is below ${r.dv} km/s.`]);if(t.budget<0)e.push(['Design exceeds available funding.','Design exceeds available funding.']);return e;}
export function hints(s){const t=stats(s),r=route(s),has=id=>s.parts.includes(id),hasCh=has('chamberA')||has('chamberB'),h=[];if(!hasCh)h.push('Start in Biology: the queens need a chamber. Economy is cheap but heavy; Vanguard holds the temperature.');if(t.use>t.power)h.push(`Your systems use ${t.use} W but the rocket gives 600 W. Engineering can add extra solar panels (+400 W).`);if(t.kg>250)h.push(`Too heavy: ${t.kg.toFixed(1)} of 250 kg. The antenna (60 kg) and panels (70 kg) are the heaviest extras.`);if(t.use<=t.power&&t.arrivalPower<t.use)h.push(`Near Mars, panels make less (NASA: Mars gets ~43% of Earth's sunlight; 85% in this game). You will make ${Math.round(t.arrivalPower)} W but use ${t.use} W: add panels or remove instruments.`);if(t.dv<r.dv)h.push(`NASA Trajectory Browser: ${r.name[0]} needs ${r.dv} km/s. Each kg costs 0.008 km/s; you have ${t.dv.toFixed(2)}.`);if(hasCh&&!has('antenna')&&!has('backup'))h.push('No antenna and no backup comms: if the signal is lost, the mission cannot talk to Earth and fails.');if(has('chamberA')&&!has('thermal')&&!has('toolkit'))h.push('The Economy chamber will raise heat alarms. A thermal sensor or a repair toolkit can save the queens.');if(hasCh&&!has('toolkit'))h.push('Without a repair toolkit, a mechanical failure keeps damaging the ship.');if(s.route==='venus')h.push('Route 3 needs 6.82 km/s: at 0.008 km/s per kg the whole ship must weigh 22 kg or less.');if(!h.length)h.push('Design looks solid. Compare routes at Mission Lead: the NASA data shows dates and delta-v.');return h;}
export function milestone(s){if(!errors(s).length&&s.grants.length===2)return 4;if(s.grants.includes(1))return 3;if(s.grants.includes(0))return 2;return 1;}
export function claim(s0,i){let s=copy(s0),t=stats(s);let ok=i===0&&s.parts.some(k=>item(k).kind==='chamber')&&t.use<=t.power&&t.kg<=250||i===1&&s.grants.includes(0)&&s.compared.length>=2;if(s.phase==='lab'&&!s.grants.includes(i)&&ok){s.grants.push(i);log(s,`Design milestone CML ${i+2}: +${CFG.grants[i]} credits.`);}return s;}
export function toggle(s0,id){let s=copy(s0),p=item(id);if(!p||s.phase!=='lab'||s.players>1&&p.role!==s.role)return s;if(s.parts.includes(id))s.parts=s.parts.filter(k=>k!==id);else{if(p.kind==='chamber')s.parts=s.parts.filter(k=>item(k).kind!=='chamber');s.parts.push(id);}return stats(s).budget<0?s0:s;}
export function chooseLauncher(s,id){return s;} export function selectRoute(s0,id){if(!ROUTES.some(r=>r.id===id)||!['lab','launch'].includes(s0.phase))return s0;let s=copy(s0);s.route=id;if(!s.compared.includes(id))s.compared.push(id);return s;}
function rand(s){s.rng=(s.rng*9301+49297)%233280;return s.rng/233280;}
export function launch(s0){if(errors(s0).length||milestone(s0)<4||s0.phase!=='launch')return s0;let s=copy(s0),r=route(s);s.phase='voyage';s.day=0;s.rng=s.seed;let events=[];if(s.parts.includes('chamberA')){events.push({kind:'thermal',day:Math.round(r.days*.35)},{kind:'thermal',day:Math.round(r.days*.7)});}else events.push({kind:'thermal',day:Math.round(r.days*.5)});events.push({kind:'comms',day:Math.round(r.days*(.45+rand(s)*.2))},{kind:'mech',day:Math.round(r.days*(.2+rand(s)*.6))});s.flight={charge:1600,temp:2.5,humidity:70,risk:0,stored:0,sent:0,lost:0,generated:0,energy:0,outages:0,pending:null,resolved:[],done:[],events,choices:[],integrity:100,damageRate:0,repairs:s.parts.includes('toolkit')?2:0,extraW:0,delayDays:0,lowTelemetry:false,commsLost:false,heat:0,minCharge:1600,stages:[]};log(s,`Launch on ${r.name} (${r.depart}). Payload ${stats(s).kg} kg. Seed ${s.seed}.`);return s;}
export const delay=s=>4+20*Math.min(1,s.day/route(s).days);export const totalDays=s=>route(s).days+(s.flight?.delayDays||0);
function check(s){let f=s.flight;for(let i=0;i<f.events.length;i++){let e=f.events[i];if(f.done.includes(i)||e.day>s.day)continue;if(e.kind==='thermal'&&s.parts.includes('chamberB')){f.done.push(i);f.choices.push('thermal:vanguard');f.risk=clamp(f.risk+1);log(s,'Heat alarm: Vanguard corrected it within minutes.');continue;}if(e.kind==='thermal'&&s.parts.includes('thermal')){f.done.push(i);f.choices.push('thermal:sensor');f.extraW+=10;f.risk=clamp(f.risk+3);log(s,'Thermal sensor caught the alarm and self-regulated (+10 W).');continue;}if(e.kind==='comms'&&s.parts.includes('backup')){f.done.push(i);let pen=f.sent*.1;f.sent-=pen;f.lost+=pen;f.choices.push('comms:backup');log(s,`Backup comms took over (-${Math.round(pen)} MB).`);continue;}if(e.kind==='comms'&&!s.parts.includes('antenna')){f.done.push(i);f.commsLost=true;s.phase='report';log(s,'Signal lost: no antenna or backup.');return;}f.pending=e.kind;f.pendingIndex=i;return;}if(s.day>=totalDays(s))s.phase='report';}
export function advance(s0){if(s0.phase!=='voyage'||s0.flight.pending)return s0;let s=copy(s0),f=s.flight,t=stats(s),days=Math.min(30,totalDays(s)-s.day);s.day+=days;let ratio=Math.min(1,s.day/route(s).days),gen=t.power*(1-.15*ratio);f.lastGen=gen;let hours=days*24,raw=f.charge+(gen-t.use)*hours;f.energy+=t.use*hours;f.charge=clamp(raw,0,1600);f.minCharge=Math.min(f.minCharge,f.charge);let out=raw<0;f.outages=out?f.outages+1:0;let v=s.parts.includes('chamberB'),sensor=s.parts.includes('thermal'),drift=v?.05:sensor?.16:.4;f.temp=2.5+(f.temp-2.5)*(v?.18:.65)+drift+(out?5:0)+f.heat;f.humidity=clamp(70+(f.humidity-70)*.65-drift*2-(out?10:0)-f.heat*2);let exp=Math.max(0,f.temp-4)*5+Math.max(0,60-f.humidity)*.5+(v?0:1.5);f.risk=clamp(f.risk+exp*days/30);f.integrity=clamp(f.integrity-(out?30:0)-f.damageRate);let prod=(s.parts.includes('dosimeter')?32:24)*(f.lowTelemetry?.5:1)*days/30;f.generated+=prod;let avail=f.stored+prod,link=s.parts.includes('antenna')?64:s.parts.includes('backup')?16:0,sent=out?0:Math.min(avail,link*days/30);f.sent+=sent;f.lost+=Math.max(0,avail-sent-128);f.stored=Math.min(128,avail-sent);f.stages.push({day:s.day,gen:Math.round(gen),use:t.use,charge:Math.round(f.charge),temp:f.temp,hum:Math.round(f.humidity),risk:Math.round(f.risk),sent:Math.round(f.sent),integ:Math.round(f.integrity)});log(s,`${days} days: ${Math.round(gen)} W made, ${t.use} W used; battery ${Math.round(f.charge)} Wh; chamber ${f.temp.toFixed(1)} C, ${Math.round(f.humidity)}% RH; risk ${Math.round(f.risk)}; +${Math.round(sent)} MB received.`);if(f.outages>=2||f.risk>=80||f.integrity<=0){s.phase='report';return s;}check(s);return s;}
export function options(s){let f=s.flight;if(s.phase!=='voyage'||!f?.pending)return [];if(f.pending==='thermal')return [{id:'repair',name:['Repair with the toolkit','Repair with the toolkit'],desc:[`Use one repair action (${f.repairs} left). The chamber is back in range.`,`Use one repair action (${f.repairs} left). The chamber is back in range.`],disabled:f.repairs<=0},{id:'battery',name:['Emergency cooling','Emergency cooling'],desc:['Spend 600 Wh of battery on a cooling pulse. Some stress remains (+12 risk).','Spend 600 Wh of battery on a cooling pulse. Some stress remains (+12 risk).'],disabled:f.charge<600},{id:'wait',name:['Ride it out','Ride it out'],desc:['Do nothing. The hive overheats: +6 C and +35 risk.','Do nothing. The hive overheats: +6 C and +35 risk.'],disabled:false}];if(f?.pending==='comms')return [{id:'realign',name:['Wait for the antenna to realign','Wait for the antenna to realign'],desc:[`Keep all data, but the trip takes ${s.parts.includes('dosimeter')?6:12} more days (more energy and exposure).${s.parts.includes('dosimeter')?' The dosimeter warned early.':''}`,`Keep all data, but the trip takes ${s.parts.includes('dosimeter')?6:12} more days (more energy and exposure).${s.parts.includes('dosimeter')?' The dosimeter warned early.':''}`],disabled:false},{id:'essentials',name:['Send essentials only','Send essentials only'],desc:[`No delay. Stored data (${Math.round(f.stored)} MB) is lost and future science is halved.`,`No delay. Stored data (${Math.round(f.stored)} MB) is lost and future science is halved.`],disabled:false}];return [{id:'fix',name:['Repair (logbook action)','Repair (logbook action)'],desc:[`Use the toolkit (${f.repairs} actions left). The trip continues normally.`,`Use the toolkit (${f.repairs} actions left). The trip continues normally.`],disabled:f.repairs<=0},{id:'power',name:['Divert power to life support','Divert power to life support'],desc:['Spend 500 Wh to keep systems up. The ship loses 20% integrity.','Spend 500 Wh to keep systems up. The ship loses 20% integrity.'],disabled:f.charge<500},{id:'continue',name:['Keep going','Keep going'],desc:['Ignore it. Damage grows every stage (-10% integrity each 30 days).','Ignore it. Damage grows every stage (-10% integrity each 30 days).'],disabled:false}];}
export function resolve(s0,id){if(s0.phase!=='voyage'||!s0.flight?.pending)return s0;let o=options(s0).find(x=>x.id===id);if(!o||o.disabled)return s0;let s=copy(s0),f=s.flight,k=f.pending;f.choices.push(`${k}:${id}`);if(k==='thermal'){if(id==='repair'){f.repairs--;f.risk=clamp(f.risk+3);}if(id==='battery'){f.charge-=600;f.energy+=600;f.risk=clamp(f.risk+12);}if(id==='wait'){f.temp+=6;f.humidity-=12;f.risk=clamp(f.risk+35);f.heat=1;}}if(k==='comms'){if(id==='realign')f.delayDays+=s.parts.includes('dosimeter')?6:12;else{f.lost+=f.stored;f.stored=0;f.lowTelemetry=true;}}if(k==='mech'){if(id==='fix')f.repairs--;if(id==='power'){f.charge-=500;f.integrity=clamp(f.integrity-20);}if(id==='continue'){f.integrity=clamp(f.integrity-15);f.damageRate=10;}}log(s,`${k}: ${o.name[0]}. ${o.desc[0]}`);f.done.push(f.pendingIndex);f.resolved.push(k);f.pending=null;if(f.risk>=80||f.integrity<=0)s.phase='report';else check(s);return s;}
export function report(s){let f=s.flight,arrived=s.day>=totalDays(s)&&f.outages<2&&f.integrity>0&&!f.commsLost,kind=!arrived||f.risk>=80?'failure':f.risk>35||f.sent<100||f.lost>64||f.integrity<50?'partial':'success';return {kind,arrived,science:s.parts.includes('dosimeter')?(s.route==='venus'?100:50):0,score:Math.max(0,Math.round((arrived?100:0)+(100-f.risk)+f.sent/4-f.lost/4+(s.parts.includes('dosimeter')&&arrived?(s.route==='venus'?100:50):0))),reason:f.commsLost?'comms':f.integrity<=0?'systems':f.outages>=2?'power':f.risk>35?'climate':f.sent<100||f.lost>64?'data':f.integrity<50?'systems':'balanced',status:f.risk>=80?'COMPROMISED':f.risk>35?'AT RISK':'GOOD'};}
export function conclusions(s){
 const f=s.flight,t=stats(s),r=report(s),rt=route(s),has=id=>s.parts.includes(id),choice=id=>f.choices.includes(id),findings=[],good=[],fix=[];
 if(r.status==='GOOD')findings.push(`The chamber kept the queens in good condition (risk index ${Math.round(f.risk)}/100, final ${f.temp.toFixed(1)} C and ${Math.round(f.humidity)}% RH, close to the 2.5 C / 70% target).`);
 else if(r.status==='AT RISK')findings.push(`The queens reached a risky state (risk index ${Math.round(f.risk)}/100). The chamber drifted away from 2.5 C / 70% RH.`);
 else findings.push(`The biological cargo was compromised (risk index ${Math.round(f.risk)}/100). The hypothesis could not be tested.`);
 if(has('chamberB'))good.push('Choosing the Vanguard chamber removed the heat alarms: active control paid off.');else if(choice('thermal:sensor'))good.push('The redundant thermal sensor caught the heat alarms in time.');
 if(choice('thermal:wait'))fix.push('Riding out a heat alarm cost +35 risk. A thermal sensor (150 cr, 0.3 kg) or a toolkit would have prevented it.');else if(choice('thermal:repair'))good.push('The toolkit fixed the heat alarm on board, without waiting for Earth.');else if(choice('thermal:battery'))fix.push('Emergency cooling used 600 Wh of battery. A sensor would have cost only 10 W.');
 const margin=t.dv-rt.dv;findings.push(`On ${rt.name[0]} (NASA Ames Trajectory Browser) the ship had ${t.dv.toFixed(2)} km/s for ${rt.dv} km/s needed: a margin of ${margin.toFixed(2)} km/s with ${t.kg.toFixed(1)} kg.`);
 if(margin<.3)fix.push('The delta-v margin was thin. Every kg costs 0.008 km/s: drop heavy extras to gain safety.');else if(t.kg<180)good.push(`A light ship (${t.kg.toFixed(1)} kg) left a comfortable delta-v margin.`);
 if(f.outages>0)findings.push(`Power ran out during the trip: near Mars the panels made about ${Math.round(t.arrivalPower)} W for ${t.use} W of use (NASA: Mars gets ~43% of Earth's sunlight).`);else findings.push(`Energy stayed positive. The lowest battery level was ${Math.round(f.minCharge)} Wh of 1600 Wh.`);
 if(t.arrivalPower<t.use)fix.push('Plan power for the arrival, not the launch: panels make less near Mars.');else if(f.outages===0)good.push('Power was planned for the whole trip, including the weaker sunlight near Mars.');
 if(f.commsLost)findings.push("Contact with NASA's Deep Space Network was lost for good: the experiment has no data to report.");else findings.push(`${Math.round(f.sent)} MB of science reached Earth and ${Math.round(f.lost)} MB were lost.`);
 if(choice('comms:backup'))good.push('The backup comms system saved the link during the solar storm.');if(choice('comms:none'))fix.push('Without an antenna or a backup link, one signal loss ends the mission. Communications are not optional.');if(choice('comms:realign'))good.push('Waiting for the antenna to realign protected all the data.');if(choice('comms:essentials'))fix.push('Sending only essentials lost the stored observations and halved later science.');
 if(has('dosimeter')&&r.arrived)good.push(`The dosimeter added radiation measurements (+${r.science} science).`);else if(!has('dosimeter'))fix.push('A dosimeter (50 cr, 0.3 kg) would add radiation data and warn of solar storms.');
 if(choice('mech:fix'))good.push('The repair toolkit fixed the impact damage with one logbook action.');if(choice('mech:continue'))fix.push(`Ignoring the impact let damage grow every stage (ship integrity ${Math.round(f.integrity)}%).`);if(choice('mech:power'))fix.push('Diverting power kept life support up but cost 20% integrity. A toolkit (150 cr) avoids it.');
 if(s.green?.done){const g=greenResult(s);findings.push(`Follow-up in the sealed Mars greenhouse (hypothetical): ${g.title.toLowerCase()}, colony index ${g.colony}/100, +${g.science} science${g.pollinated?', tomato flowers pollinated.':'.'}`);if(g.pollinated)good.push('The greenhouse experiment reached pollination: the goal of the whole mission.');else if(g.colony<60)fix.push('In the greenhouse, spend energy cells on the wake-up and the climate first: the colony comes before the data.');}
 if(t.budget>=200)good.push(`The team kept ${t.budget} credits in reserve.`);
 let verdict='ACCEPTED',vtext='The reviewers recommend publication. The mission reached Mars with the cargo in good condition and useful data.';if(r.kind==='partial'){verdict='MAJOR REVISIONS';vtext='The mission arrived, but the results are incomplete. Revise the design and fly again before publication.';}if(r.kind==='failure'){verdict='REJECTED';vtext='The experiment could not be completed. Use the comments below, redesign and resubmit.';}if(!good.length)good.push('The team completed a full design cycle and documented every decision.');if(!fix.length)fix.push('Try another NASA route or a lighter design and compare the results.');return {findings,good,fix,verdict,vtext};}

export function greenCan(s){return s.phase==='report'&&report(s).arrived&&report(s).status!=='COMPROMISED';}export function greenStart(s0){let s=copy(s0),f=s.flight;s.green={step:0,cells:2+(f.charge>=800)+(f.integrity>=80),colony:clamp(100-f.risk),lights:false,science:0,picks:[],done:false};s.phase='greenhouse';return s;}
export const greenSteps=[
{title:'WAKE THE QUEENS',text:'The queens have been dormant for the whole trip. Diapause must end gently.',careful:'Warm up slowly (7 days)',carefulDesc:'Uses 1 energy cell. Gentle wake-up: colony +15.',free:'Warm up fast (1 day)',freeDesc:'Free. A sudden change stresses the queens: colony −15.',fact:'On Earth, queens leave diapause when spring slowly warms the soil.'},
{title:'GREENHOUSE CLIMATE',text:'Mars nights are far below freezing. The sealed greenhouse needs heating to stay near 22–25 °C.',careful:'Hold a steady climate',carefulDesc:'Uses 1 energy cell. Stable nest: colony +15.',free:'Let it swing at night',freeDesc:'Free. Cold nights slow the brood: colony −20.',fact:'The greenhouse is sealed; nothing is released on Mars.'},
{title:'TOMATO FLOWERS',text:'A colony needs flowers for pollen and nectar. Plants need help in Mars sunlight.',careful:'Turn on grow lights',carefulDesc:'Uses 1 energy cell. More flowers: colony +10 and a pollination test.',free:'Natural light only',freeDesc:'Free. Few flowers: colony −10 and no pollination test.',fact:'Bumblebees shake tomato flowers to release pollen: buzz pollination.'},
{title:'REPORT TO EARTH',text:'The results travel through the Deep Space Network, with a delay of up to 24 minutes.',careful:'Send the full dataset',carefulDesc:'Uses 1 energy cell. +50 science for the paper.',free:'Send a short summary',freeDesc:'Free. +10 science.',fact:'Scientific results need data that other researchers can check.'}];
export function greenChoose(s0,careful){let s=copy(s0),g=s.green;if(!g||g.done||careful&&!g.cells)return s;if(careful)g.cells--;if(g.step<3)g.colony=clamp(g.colony+(careful?(g.step===2?10:15):(g.step===0?-15:g.step===1?-20:-10)));else g.science+=careful?50:10;if(g.step===2)g.lights=careful;g.picks.push(careful);g.step++;if(g.step===4)g.done=true;return s;}
export function greenResult(s){let g=s.green,c=Math.round(g.colony);return {colony:c,science:g.science,pollinated:c>=60&&g.lights,title:c>=60?'COLONY FOUNDED (IN THE MODEL)':c>=35?'QUEENS AWAKE, NO COLONY YET':'QUEENS DID NOT RECOVER'};}
export function redesign(s0){let s=copy(s0);s.phase='lab';s.day=0;s.flight=null;s.green=null;s.attempt++;s.seed=(s.seed*7+13)%9973;s.log=[];return s;}
export function validSave(s){return !!s&&s.version===11&&['lab','launch','voyage','report','greenhouse'].includes(s.phase)&&Number.isInteger(s.players)&&s.players>=1&&s.players<=4&&Array.isArray(s.parts)&&s.parts.every(k=>item(k))&&new Set(s.parts).size===s.parts.length&&ROUTES.some(r=>r.id===s.route)&&Array.isArray(s.grants)&&s.grants.every(i=>i===0||i===1)&&new Set(s.grants).size===s.grants.length&&Array.isArray(s.log)&&Number.isFinite(s.seed)&&(!['voyage','report','greenhouse'].includes(s.phase)||(s.flight&&Number.isFinite(s.flight.risk)&&Array.isArray(s.flight.events)))&&(s.phase!=='greenhouse'||!!s.green);}
